from collections import Counter
s=open('salad.txt').read(); t=s.split(); c=Counter(t)
print(len(t),len(c), set(v%8 for v in c.values()))
for n in (2,3,4):
 cc=Counter(tuple(t[i:i+n]) for i in range(len(t)-n+1))
 print('\\n',n)
 for g,k in cc.most_common(120):
  if k>=2: print(k,' '.join(g))
